-- Únicamente catálogos permitidos. No se exportan PK ni actores de auditoría.
-- MERGE aditivo: repetir conserva valores existentes; las FK se resuelven por clave natural.
WHENEVER OSERROR EXIT FAILURE
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF SQLBLANKLINES ON
ALTER SESSION SET TIME_ZONE='America/Guatemala';
-- Solo durante la instalación destino: conservar códigos ya asignados sin regenerarlos.
ALTER TRIGGER "TR_FERIADOS_CODIGO" DISABLE
/
ALTER TRIGGER "TR_PARAMETROS_LEGALES_CODIGO" DISABLE
/
ALTER TRIGGER "TR_TIPOS_AUSENCIA_CODIGO" DISABLE
/
ALTER TRIGGER "TR_TIPOS_CONTRATO_CODIGO" DISABLE
/
ALTER TRIGGER "TR_TIPOS_DESCUENTO_CODIGO" DISABLE
/
ALTER TRIGGER "TR_TIPOS_SOLICITUD_CODIGO" DISABLE
/

-- ROLES: 3 registros.
MERGE INTO "ROLES" D
USING (SELECT
  'ADMIN' "CODIGO",
  'Administración de sistemas' "NOMBRE",
  NULL "DESCRIPCION",
  1 "ACTIVO"
FROM DUAL) O
ON (D."CODIGO"=O."CODIGO")
WHEN NOT MATCHED THEN INSERT ("CODIGO","NOMBRE","DESCRIPCION","ACTIVO")
VALUES (O."CODIGO",O."NOMBRE",O."DESCRIPCION",O."ACTIVO")
/
MERGE INTO "ROLES" D
USING (SELECT
  'EMPLEADO' "CODIGO",
  'Empleado' "NOMBRE",
  NULL "DESCRIPCION",
  1 "ACTIVO"
FROM DUAL) O
ON (D."CODIGO"=O."CODIGO")
WHEN NOT MATCHED THEN INSERT ("CODIGO","NOMBRE","DESCRIPCION","ACTIVO")
VALUES (O."CODIGO",O."NOMBRE",O."DESCRIPCION",O."ACTIVO")
/
MERGE INTO "ROLES" D
USING (SELECT
