  TO_CLOB('CERTIFICADO PARA GESTIÓN ANTE IGSS'||CHR(10)||'{{empresa}}, NIT {{nit_empresa}}, certifica la relación laboral de {{nombre}}, DPI {{dpi}}, afiliación IGSS {{afiliacion_igss}}, desde {{fecha_ingreso}}, puesto {{puesto}}.'||CHR(10)||'Emitido el {{fecha_emision}} por {{representante}}.'||CHR(10)||'Este documento empresarial no sustituye los formularios oficiales del IGSS.') "CONTENIDO",
  TO_CLOB('["nombre","dpi","nit","puesto","departamento","fecha_ingreso","salario","afiliacion_igss","empresa","nit_empresa","direccion_empresa","representante","fecha_emision"]') "VARIABLES_PERMITIDAS",
  TO_DATE('2026-01-01T00:00:00','YYYY-MM-DD"T"HH24:MI:SS') "VIGENTE_DESDE",
  NULL "VIGENTE_HASTA",
  0 "ACTIVO",
  (SELECT ID_TIPO_SOLICITUD FROM TIPOS_SOLICITUD WHERE CODIGO='CI') "ID_TIPO_SOLICITUD"
FROM DUAL) O
ON (D."CODIGO"=O."CODIGO" AND D."VERSION"=O."VERSION")
WHEN NOT MATCHED THEN INSERT ("CODIGO","VERSION","NOMBRE","CONTENIDO","VARIABLES_PERMITIDAS","VIGENTE_DESDE","VIGENTE_HASTA","ACTIVO","ID_TIPO_SOLICITUD")
VALUES (O."CODIGO",O."VERSION",O."NOMBRE",O."CONTENIDO",O."VARIABLES_PERMITIDAS",O."VIGENTE_DESDE",O."VIGENTE_HASTA",O."ACTIVO",O."ID_TIPO_SOLICITUD")
/
