-- Reservas de los catálogos importados para evitar futuras colisiones.
MERGE INTO REGISTRO_CODIGOS D
USING (SELECT 'tipos-contrato' ENTIDAD,CODIGO,MAX(CODIGO_ANTERIOR) LEGADO FROM TIPOS_CONTRATO GROUP BY CODIGO) O
ON (D.ENTIDAD=O.ENTIDAD AND D.CODIGO=O.CODIGO)
WHEN NOT MATCHED THEN INSERT (ENTIDAD,CODIGO,LEGADO) VALUES (O.ENTIDAD,O.CODIGO,O.LEGADO)
/
MERGE INTO REGISTRO_CODIGOS D
USING (SELECT 'tipos-descuento' ENTIDAD,CODIGO,MAX(CODIGO_ANTERIOR) LEGADO FROM TIPOS_DESCUENTO GROUP BY CODIGO) O
ON (D.ENTIDAD=O.ENTIDAD AND D.CODIGO=O.CODIGO)
WHEN NOT MATCHED THEN INSERT (ENTIDAD,CODIGO,LEGADO) VALUES (O.ENTIDAD,O.CODIGO,O.LEGADO)
/
