/
MERGE INTO REGISTRO_CODIGOS D
USING (SELECT 'parametros-legales' ENTIDAD,CODIGO,MAX(CLAVE_INTERNA) LEGADO FROM PARAMETROS_LEGALES GROUP BY CODIGO) O
ON (D.ENTIDAD=O.ENTIDAD AND D.CODIGO=O.CODIGO)
WHEN NOT MATCHED THEN INSERT (ENTIDAD,CODIGO,LEGADO) VALUES (O.ENTIDAD,O.CODIGO,O.LEGADO)
/
MERGE INTO REGISTRO_CODIGOS D
USING (SELECT 'feriados' ENTIDAD,CODIGO,MAX(CODIGO_ANTERIOR) LEGADO FROM FERIADOS GROUP BY CODIGO) O
ON (D.ENTIDAD=O.ENTIDAD AND D.CODIGO=O.CODIGO)
WHEN NOT MATCHED THEN INSERT (ENTIDAD,CODIGO,LEGADO) VALUES (O.ENTIDAD,O.CODIGO,O.LEGADO)
/
COMMIT;
